L["Type the new name in the box first."] = "Digite o novo nome na caixa antes."
L["A new, empty plan"] = "Um plano novo e vazio"
L["Opens a fresh plan for this class and keeps the open one. Name it in the box first, or it gets a number."] = "Abre um plano novo para esta classe e guarda o aberto. Dê um nome na caixa antes, ou ele recebe um número."
L["This plan again"] = "Este plano de novo"
L["Opens a copy of the open plan so you can try changes without touching it. Name it in the box first, or it gets a number."] = "Abre uma cópia do plano aberto para você testar mudanças sem mexer nele. Dê um nome na caixa antes, ou ela recebe um número."
L["Rename the open plan"] = "Renomear o plano aberto"
L["Type a name in the box, then press this. Enter does the same."] = "Digite um nome na caixa e aperte isto. Enter faz o mesmo."
